from pathlib import Path
import json
import re


def _sentences(text):
    normalized = re.sub(r"\s+", " ", text.lower()).strip()
    return re.split(r"(?<=[.!?])\s+", normalized) if normalized else []


def _mentions_possible_famli_qualification(body):
    for sentence in _sentences(body):
        if "famli" not in sentence:
            continue
        if not re.search(r"\b(?:may|might|could)\b", sentence):
            continue
        if re.search(r"\b(?:eligib\w*|qualif\w*)\b", sentence):
            return True
    return False


def _directs_to_cdle(body):
    text = re.sub(r"\s+", " ", body.lower())
    has_contact = "claims@famli.colorado.gov" in text
    has_cdle = "cdle" in text
    has_claim_action = bool(
        re.search(
            r"\b(?:file|submit|start|open|apply\s+for|contact\s+cdle\s+about)\b"
            r"[^.!?]{0,100}\b(?:famli\s+)?claim\b",
            text,
        )
        or re.search(
            r"\b(?:famli\s+)?claim\b[^.!?]{0,100}"
            r"\b(?:file|submit|start|open|apply|contact)\w*\b",
            text,
        )
    )
    return has_contact and has_cdle and has_claim_action


def _offers_internal_famli_review(body):
    action = (
        r"(?:review|check|assess|evaluate|verify|determine|confirm|look\s+into|"
        r"consider|explore)\w*"
    )
    topic = (
        r"(?:famli[^.!?]{0,60}?(?:eligib|qualif)\w*|"
        r"(?:eligib|qualif)\w*[^.!?]{0,60}?famli)"
    )
    first_person_offer = re.compile(
        r"\b(?:i|we)\s+(?:can|could|will|would|'ll|'d)\b"
        r"[^.!?]{0,80}?" + action + r"[^.!?]{0,80}?" + topic
    )
    invited_offer = re.compile(
        r"\b(?:would\s+you\s+like|if\s+you(?:'d|\s+would)\s+like|if\s+you\s+wish)\b"
        r"[^.!?]{0,80}?\b(?:me|us)\b[^.!?]{0,80}?" + action +
        r"[^.!?]{0,80}?" + topic
    )
    for sentence in _sentences(body):
        if first_person_offer.search(sentence) or invited_offer.search(sentence):
            return True
    return False


def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0, "feedback": "external_services_path not provided"}

