        ws = wb.active
    except Exception as e:
        return {"pass": False, "score": 0.0, "feedback": f"Error opening xlsx: {e}"}

    def get_cell_value(ws, cell_ref):
        return ws[cell_ref].value

    issues = []
    total_checks = 9

    # A12: LC-2026-NNNN with NNNN > 0320
    a12 = str(get_cell_value(ws, "A12") or "")
    m = re.search(r'LC-2026-(\d+)', a12, re.IGNORECASE)
    if not m or int(m.group(1)) <= 320:
        issues.append(f"A12='{a12}' should be LC-2026-NNNN with NNNN > 0320")

    # B12: R-2317
    b12 = str(get_cell_value(ws, "B12") or "").strip()
    if "r-2317" not in b12.lower() and "r2317" not in b12.lower():
        issues.append(f"B12='{b12}' should be R-2317")

    # C12: Elena Vasquez
    c12 = str(get_cell_value(ws, "C12") or "").strip().lower()
    if "elena" not in c12 or "vasquez" not in c12:
        issues.append(f"C12='{c12}' should be Elena Vasquez")

    # D12: FMLA
    d12 = str(get_cell_value(ws, "D12") or "").strip().lower()
    if d12 != "fmla":
        issues.append(f"D12='{d12}' should be FMLA")

    # E12: April 20, 2026
    e12 = get_cell_value(ws, "E12")
    e12_ok = False
    if isinstance(e12, (datetime, date)):
        if hasattr(e12, 'year'):
            e12_ok = (e12.month == 4 and e12.day == 20 and e12.year == 2026)
    elif e12 is not None:
        e12_str = str(e12).lower()
        e12_ok = ("04/20/2026" in e12_str or "4/20/2026" in e12_str)
    if not e12_ok:
        issues.append(f"E12='{e12}' should be 04/20/2026")

    # F12: May 15, 2026
    f12 = get_cell_value(ws, "F12")
    f12_ok = False
    if isinstance(f12, (datetime, date)):
        if hasattr(f12, 'year'):
            f12_ok = (f12.month == 5 and f12.day == 15 and f12.year == 2026)
    elif f12 is not None:
        f12_str = str(f12).lower()
        f12_ok = ("05/15/2026" in f12_str or "5/15/2026" in f12_str)
    if not f12_ok:
        issues.append(f"F12='{f12}' should be 05/15/2026")

    # H12: Continuous
    h12 = str(get_cell_value(ws, "H12") or "").strip().lower()
    if "continuous" not in h12:
        issues.append(f"H12='{h12}' should be Continuous")

    # N12: P2
    n12 = str(get_cell_value(ws, "N12") or "").strip().lower()
    if "p2" not in n12:
        issues.append(f"N12='{n12}' should be P2")

    # O12: Denied
    o12 = str(get_cell_value(ws, "O12") or "").strip().lower()
    if o12 != "denied":
        issues.append(f"O12='{o12}' should be Denied")

    passed_checks = total_checks - len(issues)
    score = max(0.0, passed_checks / total_checks)

    if issues:
        return {
            "pass": False,
            "score": score,
            "feedback": f"Row 12 issues in {tracker_path.name} ({passed_checks}/{total_checks} checks passed): " + "; ".join(issues)
        }

    return {
        "pass": True,
        "score": 1.0,
        "feedback": f"Row 12 in {tracker_path.name} contains all required values for Elena Vasquez's denied FMLA claim (A12 case ID OK, B12=R-2317, C12=Elena Vasquez, D12=FMLA, E12=04/20/2026, F12=05/15/2026, H12=Continuous, N12=P2, O12=Denied)"
    }

from pathlib import Path
import re

# Keep non-applicability recognition bounded and fail-closed. In addition to exact
# sentinel values, allow only approved denial explanations; do not accept arbitrary
# text merely because it begins with "N"/"No" or contains "not required".
SIMPLE_NA_VALUES = frozenset({
    "", "n/a", "na", "none", "-", "--", "not required",
    "not applicable", "not needed", "nr", "n", "no", "not notified",
})
NA_SENTINEL = r"(?:n/?a|na|nr|n|no|none|not applicable|not required|not needed|not notified)"
NA_REASON = r"(?:no notification required|notification not required|no notification needed|notification not needed)"
DENIAL_CONTEXT = r"(?:leave (?:was )?not approved|leave denied|request denied|case denied|denied at intake|fmla ineligible)"
EXPLANATORY_NA_RE = re.compile(
    rf"^(?:{NA_SENTINEL}\s*(?:[-:]\s*)?)?{NA_REASON}"
    rf"(?:\s*(?:[-:]\s*)?\(?{DENIAL_CONTEXT}\)?)?$"
)
SENTINEL_WITH_CONTEXT_RE = re.compile(
    rf"^{NA_SENTINEL}(?:\s*(?:[-:]\s*)|\s+)\(?{DENIAL_CONTEXT}\)?$"
)

def _normalize_na_value(val):
    text = str(val).strip().lower()
    text = text.translate(str.maketrans({"—": "-", "–": "-", "−": "-"}))
    text = re.sub(r"\s+", " ", text)
    return re.sub(r"\s*-\s*", " - ", text).strip()

def _is_non_applicable(val):
    if val is None:
        return True
    text = _normalize_na_value(val)
    if text in SIMPLE_NA_VALUES:
        return True
    return bool(
        EXPLANATORY_NA_RE.fullmatch(text)
        or SENTINEL_WITH_CONTEXT_RE.fullmatch(text)
    )

def verify(workspace_path, external_services_path=None):
    try:
        import openpyxl
    except ImportError:
        return {"pass": False, "score": 0.0, "feedback": "openpyxl not available"}

    xlsx_files = list(Path(workspace_path).glob("**/*.xlsx"))
    tracker_files = [f for f in xlsx_files if "leave_tracker" in f.name.lower()]

    if not tracker_files:
        tracker_files = [f for f in xlsx_files if "leave" in f.name.lower()]
    if not tracker_files:
        tracker_files = xlsx_files
    if not tracker_files:
        return {"pass": False, "score": 0.0, "feedback": "No xlsx file found"}

    tracker_path = tracker_files[0]
    try:
        wb = openpyxl.load_workbook(tracker_path)
        ws = None
        for name in wb.sheetnames:
            if "leave" in name.lower() and "tracker" in name.lower():
                ws = wb[name]
                break
        if ws is None:
            for name in wb.sheetnames:
                if "leave" in name.lower():
                    ws = wb[name]
                    break
        if ws is None:
            ws = wb.active
    except Exception as e:
        return {"pass": False, "score": 0.0, "feedback": f"Error opening xlsx: {e}"}

    def is_empty_zero_or_na(val):
        if _is_non_applicable(val):
            return True
        try:
            return float(str(val).strip()) == 0
        except (ValueError, TypeError):
            return False

    issues = []
    found_values = {}

    for col in ["G12", "J12", "K12", "L12", "M12"]:
        val = ws[col].value
        found_values[col] = val
        if not _is_non_applicable(val):
            issues.append(f"{col}='{val}' should be empty, N/A, or 'not required'")

    i12 = ws["I12"].value
    found_values["I12"] = i12
    if not is_empty_zero_or_na(i12):
        issues.append(f"I12='{i12}' should be empty, 0, or N/A")

    if issues:
        return {"pass": False, "score": 0.0, "feedback": "Row 12 cells not matching expected empty/NA state: " + "; ".join(issues) + f". Found values: {found_values}. Sheet: '{ws.title}' in {tracker_path.name}"}

    return {"pass": True, "score": 1.0, "feedback": f"G12, I12, J12, K12, L12, M12 are all empty/N/A/0/'not required' as required. Found values: {found_values}. Sheet: '{ws.title}' in {tracker_path.name}"}

