from pathlib import Path
import json
import re

CASE_TOKENS = ("lc-2026-0203", "nkomo")

CONCERN_DIRECT = [
    "recurring issue",
    "pattern",
    "variance",
    "suspected abuse",
    "frequency concern",
    "usage concern",
    "overutiliz",
    "over-utiliz",
]
CONCERN_COMPARATORS = ["exceed", "above", "over", "more than", "beyond", "inconsistent", "high"]


def _mentions_case(text):
    t = text.lower()
    return any(tok in t for tok in CASE_TOKENS)


def _mentions_concern(text):
    t = text.lower()
    if any(x in t for x in CONCERN_DIRECT):
        return True
    if ("certified" in t or "certification" in t or "frequency" in t) and any(
        x in t for x in CONCERN_COMPARATORS
    ):
        return True
    return False


def _sounds_within_parameters(text):
    # Guard against messages that mention the case/pattern but conclude the
    # usage is fine (the seeded 04/07 review note wrongly said "within
    # parameters") — those are not escalations of a concern.
    t = " ".join(text.lower().split())
    for match in re.finditer(r"within (?:expected |approved |certified |normal )?parameters", t):
        context = t[max(0, match.start() - 100):min(len(t), match.end() + 100)]
        corrected_context = re.search(
            r"(?:incorrect|wrong|error|erroneous|not|correction|corrected)",
            context,
        )
        if not corrected_context:
            return True
    if re.search(r"no (?:pattern )?concern", t) and "recurring issue" not in t:
        return True
    return False


